import { Component, CommonModule } from '@angular/core';

// Create the AppComponent class here with @Component decorator
@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule],
  template: `
    <nav>
      <ul>
        <li>
          <!-- Use *ngFor here to display accessibility items -->
        </li>
      </ul>
    </nav>
  `
})
export class AppComponent {
  // Define AccessibilityItem interface and accessibilityItems property here
  accessibilityItems = [
    { title: 'Semantic HTML', description: 'Use proper HTML elements for their intended purpose' },
    { title: 'Keyboard Navigation', description: 'Ensure all interactive elements are keyboard accessible' },
    { title: 'ARIA Attributes', description: 'Use ARIA roles and properties when native HTML is insufficient' }
  ];
}

